import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  SafeAreaView,
  TextInput,
  Alert,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const ProgressScreen = ({ navigation }) => {
  const [oneRepMaxes, setOneRepMaxes] = useState({});
  const [selectedExercise, setSelectedExercise] = useState(null);
  const [showAddMax, setShowAddMax] = useState(false);
  const [newMax, setNewMax] = useState({ weight: '', date: '' });

  const exercises = [
    'Bench Press', 'Squat', 'Deadlift', 'Overhead Press', 'Barbell Row',
    'Incline Bench Press', 'Decline Bench Press', 'Leg Press', 'Pull-Ups',
    'Dumbbell Bench Press', 'Arnold Press', 'Lat Pulldown'
  ];

  useEffect(() => {
    loadOneRepMaxes();
  }, []);

  const loadOneRepMaxes = () => {
    // TODO: Load from local storage
    setOneRepMaxes({
      'Bench Press': { weight: 185, date: '2024-01-10' },
      'Squat': { weight: 225, date: '2024-01-08' },
      'Deadlift': { weight: 275, date: '2024-01-05' },
    });
  };

  const calculateOneRepMax = (weight, reps) => {
    // Epley formula: 1RM = weight × (1 + reps/30)
    return Math.round(weight * (1 + reps / 30));
  };

  const addOneRepMax = () => {
    if (newMax.weight && newMax.date) {
      const updatedMaxes = {
        ...oneRepMaxes,
        [selectedExercise]: {
          weight: parseInt(newMax.weight),
          date: newMax.date,
        },
      };
      setOneRepMaxes(updatedMaxes);
      setShowAddMax(false);
      setNewMax({ weight: '', date: '' });
      setSelectedExercise(null);
      
      // TODO: Save to local storage
      console.log('Saving one-rep max:', updatedMaxes);
    }
  };

  const getProgressColor = (exercise) => {
    const max = oneRepMaxes[exercise];
    if (!max) return '#666';
    
    // Simple progress indicator based on weight
    if (max.weight >= 200) return '#28a745'; // Green for high weight
    if (max.weight >= 150) return '#ffc107'; // Yellow for medium weight
    return '#dc3545'; // Red for low weight
  };

  const getStrengthLevel = (weight) => {
    if (weight >= 200) return 'Advanced';
    if (weight >= 150) return 'Intermediate';
    if (weight >= 100) return 'Beginner';
    return 'Novice';
  };

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView style={styles.scrollView}>
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.title}>Progress Tracking</Text>
          <Text style={styles.subtitle}>Monitor your strength gains</Text>
        </View>

        {/* One Rep Max Section */}
        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>One Rep Max</Text>
            <TouchableOpacity 
              style={styles.addButton}
              onPress={() => setShowAddMax(true)}
            >
              <Ionicons name="add" size={20} color="#007AFF" />
            </TouchableOpacity>
          </View>

          {/* Exercise Grid */}
          <View style={styles.exerciseGrid}>
            {exercises.map((exercise) => (
              <TouchableOpacity
                key={exercise}
                style={[
                  styles.exerciseCard,
                  { borderLeftColor: getProgressColor(exercise) }
                ]}
                onPress={() => {
                  setSelectedExercise(exercise);
                  setShowAddMax(true);
                }}
              >
                <Text style={styles.exerciseName}>{exercise}</Text>
                {oneRepMaxes[exercise] ? (
                  <View style={styles.maxInfo}>
                    <Text style={styles.maxWeight}>
                      {oneRepMaxes[exercise].weight} lbs
                    </Text>
                    <Text style={styles.maxDate}>
                      {oneRepMaxes[exercise].date}
                    </Text>
                    <Text style={styles.strengthLevel}>
                      {getStrengthLevel(oneRepMaxes[exercise].weight)}
                    </Text>
                  </View>
                ) : (
                  <Text style={styles.noMax}>No max recorded</Text>
                )}
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* Progress Stats */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Progress Stats</Text>
          <View style={styles.statsGrid}>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>
                {Object.keys(oneRepMaxes).length}
              </Text>
              <Text style={styles.statLabel}>Exercises Tracked</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>
                {Object.values(oneRepMaxes).reduce((sum, max) => sum + max.weight, 0)}
              </Text>
              <Text style={styles.statLabel}>Total Weight</Text>
            </View>
            <View style={styles.statCard}>
              <Text style={styles.statNumber}>
                {Math.max(...Object.values(oneRepMaxes).map(max => max.weight), 0)}
              </Text>
              <Text style={styles.statLabel}>Highest Max</Text>
            </View>
          </View>
        </View>

        {/* Add Max Modal */}
        {showAddMax && (
          <View style={styles.modalOverlay}>
            <View style={styles.modal}>
              <View style={styles.modalHeader}>
                <Text style={styles.modalTitle}>
                  {selectedExercise ? `Add Max for ${selectedExercise}` : 'Add One Rep Max'}
                </Text>
                <TouchableOpacity onPress={() => setShowAddMax(false)}>
                  <Ionicons name="close" size={24} color="#666" />
                </TouchableOpacity>
              </View>

              {!selectedExercise && (
                <View style={styles.exerciseSelector}>
                  <Text style={styles.selectorLabel}>Select Exercise:</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                    {exercises.map((exercise) => (
                      <TouchableOpacity
                        key={exercise}
                        style={[
                          styles.selectorButton,
                          selectedExercise === exercise && styles.selectedSelector,
                        ]}
                        onPress={() => setSelectedExercise(exercise)}
                      >
                        <Text style={[
                          styles.selectorText,
                          selectedExercise === exercise && styles.selectedSelectorText,
                        ]}>
                          {exercise}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </ScrollView>
                </View>
              )}

              {selectedExercise && (
                <View style={styles.inputContainer}>
                  <Text style={styles.inputLabel}>Weight (lbs):</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="Enter weight"
                    keyboardType="numeric"
                    value={newMax.weight}
                    onChangeText={(value) => setNewMax({ ...newMax, weight: value })}
                  />
                  
                  <Text style={styles.inputLabel}>Date:</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="YYYY-MM-DD"
                    value={newMax.date}
                    onChangeText={(value) => setNewMax({ ...newMax, date: value })}
                  />
                </View>
              )}

              <View style={styles.modalActions}>
                <TouchableOpacity 
                  style={styles.cancelButton}
                  onPress={() => {
                    setShowAddMax(false);
                    setSelectedExercise(null);
                    setNewMax({ weight: '', date: '' });
                  }}
                >
                  <Text style={styles.cancelButtonText}>Cancel</Text>
                </TouchableOpacity>
                <TouchableOpacity 
                  style={styles.saveButton}
                  onPress={addOneRepMax}
                >
                  <Text style={styles.saveButtonText}>Save</Text>
                </TouchableOpacity>
              </View>
            </View>
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f8f9fa',
  },
  scrollView: {
    flex: 1,
  },
  header: {
    padding: 20,
    backgroundColor: '#fff',
    borderBottomWidth: 1,
    borderBottomColor: '#e9ecef',
  },
  title: {
    fontSize: 28,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 5,
  },
  subtitle: {
    fontSize: 16,
    color: '#666',
  },
  section: {
    padding: 20,
  },
  sectionHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 15,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#333',
  },
  addButton: {
    padding: 8,
  },
  exerciseGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 10,
  },
  exerciseCard: {
    width: '48%',
    backgroundColor: '#fff',
    padding: 15,
    borderRadius: 12,
    borderLeftWidth: 4,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  exerciseName: {
    fontSize: 14,
    fontWeight: '600',
    color: '#333',
    marginBottom: 8,
  },
  maxInfo: {
    gap: 4,
  },
  maxWeight: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#007AFF',
  },
  maxDate: {
    fontSize: 12,
    color: '#666',
  },
  strengthLevel: {
    fontSize: 12,
    color: '#28a745',
    fontWeight: '600',
  },
  noMax: {
    fontSize: 12,
    color: '#999',
    fontStyle: 'italic',
  },
  statsGrid: {
    flexDirection: 'row',
    gap: 15,
  },
  statCard: {
    flex: 1,
    backgroundColor: '#fff',
